import sys
def solve(n, edges, queries):
    from collections import defaultdict
    adj = defaultdict(list)
    for u, v in edges: adj[u].append(v); adj[v].append(u)
    LOG = 18; up = [[-1] * LOG for _ in range(n + 1)]
    visited = [False] * (n + 1); stack = [(1, 0, 0)]
    while stack:
        node, p, d = stack.pop()
        if visited[node]: continue
        visited[node] = True; up[node][0] = p if p else -1
        for i in range(1, LOG):
            if up[node][i-1] != -1: up[node][i] = up[up[node][i-1]][i-1]
        for nb in adj[node]:
            if not visited[nb]: stack.append((nb, node, d + 1))
    res = []
    for node, k in queries:
        cur = node
        for i in range(LOG):
            if (k >> i) & 1:
                if cur == -1: break
                cur = up[cur][i]
        res.append(str(cur) if cur != -1 else "-1")
    return "\n".join(res)

if __name__ == '__main__':
    data = sys.stdin.read().split()
    idx = 0
    n, m = int(data[idx]), int(data[idx+1]); idx += 2
    edges = []
    for _ in range(m): edges.append((int(data[idx]), int(data[idx+1]))); idx += 2
    q = int(data[idx]); idx += 1
    queries = []
    for _ in range(q): queries.append((int(data[idx]), int(data[idx+1]))); idx += 2
    print(solve(n, edges, queries))

